L5_1.m_Crash = 10
L5_1.m_Talk_KOREA = "말했었잖니, 지아야."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "言ったじゃないか、ユイ。"
L5_1.m_Talk_ENG = "Didn’t I tell you already, Jia?"
L5_1.m_Talk_TWN = "我不是跟你說嗎？"
L5_1.m_Talk_THA = "ก็บอกแล้วไม่ใช่เหรอเจีย?"
L5_1.m_Talk_VTN = "Tao chưa nói ư, Jia?"
L5_1.m_Talk_SCN = "我不是说过吗，小佳。"
L5_1.m_Talk_DEU = "Ich sagte es doch, Jia."
L5_1.m_Talk_FRA = "Je te l'avais pourtant dit, Jia."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE2_START@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 3900305
L6_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L6_1.m_Pos = "L"
L6_1.m_Talk_KOREA = "조만간 그 병실에서 일어나 쌩쌩하게 걸어 다닐 거라고."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "近いうちにあの病室を出て、元気に歩けるようになると。"
L6_1.m_Talk_ENG = "I’ll soon get better and walk out of this place."
L6_1.m_Talk_TWN = "爺爺很快就會康復出院的。"
L6_1.m_Talk_THA = "ว่าอีกไม่นานปู่ก็จะหายป่วยและเดินออกจากที่นี่"
L6_1.m_Talk_VTN = "Rằng tao sẽ sớm khỏe lại và bước ra khỏi nơi này."
L6_1.m_Talk_SCN = "很快就会从病床上重新站起来，恢复如初。"
L6_1.m_Talk_DEU = "Dass ich bald aus dem Krankenbett aufstehen und wacker herumlaufen werde."
L6_1.m_Talk_FRA = "Que je sortirais bientôt de l'hôpital et en pleine forme."
L7_1 = {}
L7_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE2_START@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 3900305
L7_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_DESPAIR"
L7_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L7_1.m_Pos = "R"
L7_1.m_Crash = 10
L7_1.m_Talk_KOREA = "그 말……. 할아버님께서 종종 하시던……."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "その言葉……お祖父様が度々話していた……"
L7_1.m_Talk_ENG = "That’s... what Grandfather used to say..."
L7_1.m_Talk_TWN = "那句話……爺爺常掛在嘴邊……"
L7_1.m_Talk_THA = "คุณปู่... เคยพูดแบบนั้น..."
L7_1.m_Talk_VTN = "Đó là... điều mà Ông Nội thường nói..."
L7_1.m_Talk_SCN = "那些话……爷爷曾经说过的那些……"
L7_1.m_Talk_DEU = "Das hat mein Großvater oft gesagt ..."
L7_1.m_Talk_FRA = "Ces mots... Mon grand-père les disait souvent..."
