L9_1.m_Pos = "C"
L9_1.m_Crash = 20
L9_1.m_Talk_KOREA = "설마, 정말 할아버님……?"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "まさか、本当にお祖父様……？"
L9_1.m_Talk_ENG = "A-are you really Grandfather...?"
L9_1.m_Talk_TWN = "難道你真的是爺爺……？"
L9_1.m_Talk_THA = "คะ-คุณคือคุณปู่จริงๆ เหรอคะ...?"
L9_1.m_Talk_VTN = "C-cô thực sự là ông nội sao...?"
L9_1.m_Talk_SCN = "难道，真的是爷爷……？"
L9_1.m_Talk_DEU = "Sind Sie etwa wirklich mein Großvater ...?"
L9_1.m_Talk_FRA = "Alors vous êtes vraiment grand-père... ?"
