L11_1 = {}
L11_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE2_START@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 3900305
L11_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_SERIOUS"
L11_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L11_1.m_Pos = "C"
L11_1.m_Crash = 10
L11_1.m_Talk_KOREA = "속지 마세요, 리더. 단순한 성문 변조기에 불과합니다."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "騙されないでください、リーダー。単なるボイスチェンジャーにすぎません。"
L11_1.m_Talk_ENG = "Don’t be fooled, Leader. She’s just using a voice modulator."
L11_1.m_Talk_TWN = "老大，你別上當，那不過就是變聲器而已！"
L11_1.m_Talk_THA = "อย่าโดนหลอกนะท่านผู้นำ เธอแค่ใช้เครื่องเปลี่ยนเสียง"
L11_1.m_Talk_VTN = "Đừng để bị lừa, Thủ Lĩnh. Cô ta chỉ đang sử dụng bộ điều biến giọng nói thôi."
L11_1.m_Talk_SCN = "别被骗了，队长。她只是使用了变声器而已。"
L11_1.m_Talk_DEU = "Nicht darauf reinfallen, Anführerin. Das ist nur ein Stimmenmodulator."
L11_1.m_Talk_FRA = "Ne vous faites pas avoir chef. C'est simplement un transformateur de voix."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE2_START@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 3900305
L12_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L12_1.m_Pos = "C"
L12_1.m_Talk_KOREA = "저 자는 회장이 아니에요. 음성으로 혼란을 야기하는 건 흔한 속임수예요."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "あれは会長ではありません。音声で惑わすのはよくあるトリックです。"
L12_1.m_Talk_ENG = "She’s not the President. It’s another one of her tricks to cause confusion."
L12_1.m_Talk_TWN = "她不是會長！利用聲音來引起混亂是常見的詐騙手法。"
L12_1.m_Talk_THA = "เธอไม่ใช่ท่านประธาน นี่แค่อีกลูกเล่นที่เธอใช้ทำให้สับสน"
L12_1.m_Talk_VTN = "Cô ấy không phải là Chủ Tịch. Đó là một trong những thủ thuật khác của cô ta để gây rối thôi."
L12_1.m_Talk_SCN = "那个人不是会长。模仿他人的声音让对手陷入混乱是很常见的骗术。"
L12_1.m_Talk_DEU = "Sie ist nicht der Vorsitzende. Es ist ein alter Trick, per Stimme Verwirrung zu stiften."
L12_1.m_Talk_FRA = "Ce n'est pas le président. C'est un stratagème pour vous faire douter."
