L15_1 = {}
L15_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE2_START@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 3900305
L15_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_HATE"
L15_1.m_CharStrID = "SEAROM_ALPHA_NULL_NULL"
L15_1.m_Pos = "L"
L15_1.m_Crash = 10
L15_1.m_Talk_KOREA = "초원이 말이 맞아! 회장님은 죽은 지 한참 지났잖아!"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "ナオちゃんの言うとおりだよ！　会長はずっと昔に亡くなってるじゃん！"
L15_1.m_Talk_ENG = "Chowon’s right! The President passed away a long time ago!"
L15_1.m_Talk_TWN = "初源說得沒錯！會長都已經過世這麼久了！"
L15_1.m_Talk_THA = "ถูกของโชวอนค่ะ! ท่านประธานเสียไปตั้งนานแล้วนะคะ!"
L15_1.m_Talk_VTN = "Chowon nói đúng! Chủ Tịch đã qua đời lâu lắm rồi!"
L15_1.m_Talk_SCN = "桃沢梨绘说得对！会长过世已经很久了！"
L15_1.m_Talk_DEU = "Chowon hat recht! Der Vorsitzende ist schon längst tot!"
L15_1.m_Talk_FRA = "Chowon a raison ! Le président est mort il y a très longtemps !"
L16_1 = {}
L16_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE2_START@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 3900305
L16_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "CHOI_ALPHA_NULL_SHORT"
L16_1.m_Pos = "R"
L16_1.m_Crash = 20
L16_1.m_Talk_KOREA = "그렇다, 대장. 아무리 그리워도 죽은 사람은 두 번 다시 돌아오지 않아."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "そのとおりだ、隊長。どんなに恋しくても、死んだ人間は二度と戻らない。"
L16_1.m_Talk_ENG = "She’s right, Cap. The dead don’t come back to life, no matter how much you miss them."
L16_1.m_Talk_TWN = "沒錯，隊長。我知道你很想念會長，但死人是不會復活的。"
L16_1.m_Talk_THA = "จริงของนางนะแคป คนเราตายแล้วมิอาจหวนคืน ไม่ว่าเราจะคิดถึงเพียงใดก็ตาม"
L16_1.m_Talk_VTN = "Cô ấy nói đúng, Đội Trưởng. Người chết không sống lại, cho dù cô có nhớ họ đến thế nào đi chăng nữa."
L16_1.m_Talk_SCN = "是啊，队长。就算你很怀念故去的人，但他也不会死而复生。"
L16_1.m_Talk_DEU = "Stimmt, Cap. Sehnsucht bringt einen toten Menschen nicht zurück."
L16_1.m_Talk_FRA = "C'est vrai chef. Un mort ne peut pas revenir à la vie."
