L20_1 = 1.3
L21_1 = 1.3
L19_1[1] = L20_1
L19_1[2] = L21_1
L18_1.m_CharScale = L19_1
L18_1.m_CharScaleTime = 0.01
L18_1.m_Crash = 10
L18_1.m_Talk_KOREA = "덜떨어진 머저리들. 네놈들이 모르는 건 세상에 없는 줄 아나?"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "アルファトリックス・イノベーションは間抜けどもの寄せ集めかしら。\nあんたたちが知らないことはこの世にないとでも？"
L18_1.m_Talk_ENG = "Fools! You think you know everything there is to know about this world?"
L18_1.m_Talk_TWN = "愚昧的傢伙們！你們不知道，不代表就不存在於這個世界上。"
L18_1.m_Talk_THA = "พวกโง่! คิดว่ารู้ทุกเรื่องในโลกนี้แล้วรึไง?"
L18_1.m_Talk_VTN = "Một đám ngu ngốc! Chúng mày tưởng mình biết tất cả mọi thứ cần biết về thế giới này sao?"
L18_1.m_Talk_SCN = "你们这些蠢货。你们自以为知道了世界上所有的事情吗？"
L18_1.m_Talk_DEU = "Ihr belämmerten Idioten. Glaubt ihr, dass die Welt, wie ihr sie kennt, alles ist?"
L18_1.m_Talk_FRA = "Bande d'idiots. Ce n'est pas parce que vous ne savez pas certaines choses qu'elles n'existent pas !"
L19_1 = {}
L19_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE2_START@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 3900305
L19_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L19_1.m_Pos = "C"
L20_1 = {}
L21_1 = 1.3
L22_1 = 1.3
L20_1[1] = L21_1
L20_1[2] = L22_1
L19_1.m_CharScale = L20_1
L19_1.m_CharScaleTime = 0.01
L19_1.m_Talk_KOREA = "나는 회장의 생전 기억과 경험을 전부 이식했다."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "この体には会長の生前の記憶と経験をすべて移植した。"
L19_1.m_Talk_ENG = "I have all of my father’s memories and experiences implanted in my head."
L19_1.m_Talk_TWN = "我移植了會長生前的全部記憶和經驗。"
L19_1.m_Talk_THA = "ฉันปลูกถ่ายความทรงจำและประสบการณ์ทั้งหมดของพ่อลงในหัว"
L19_1.m_Talk_VTN = "Tất cả ký ức và trải nghiệm của cha ta đều đã được cấy vào đầu ta."
L19_1.m_Talk_SCN = "父亲生前全部的记忆和经验，都被我移植到了我的脑海里。"
L19_1.m_Talk_DEU = "Ich habe mir sämtliche Erinnerungen und Erfahrungen des Vorsitzenden implantieren lassen."
L19_1.m_Talk_FRA = "J'ai transplanté tous les souvenirs et les expériences du président."
L20_1 = {}
