L21_1 = {}
L22_1 = 1.3
L23_1 = 1.3
L21_1[1] = L22_1
L21_1[2] = L23_1
L20_1.m_CharScale = L21_1
L20_1.m_CharScaleTime = 0.01
L20_1.m_Talk_KOREA = "워낙 분량이 방대해서 아직도 완전히 정착하진 않았지만……."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "あまりにも量が膨大で、まだ完全に定着していないけど……"
L20_1.m_Talk_ENG = "Although it hasn’t fully set in as it is a vast amount of data..."
L20_1.m_Talk_TWN = "不過因為量有點龐大，所以還沒完全載入……"
L20_1.m_Talk_THA = "ถีงมันจะไม่อยู่ตัวทั้งหมดเพราะข้อมูลมีจำนวนมหาศาล..."
L20_1.m_Talk_VTN = "Mặc dù nó chưa hoàn chỉnh vì khối lượng lớn dữ liệu quá lớn..."
L20_1.m_Talk_SCN = "虽然因为信息量过于庞大，现在没能完全掌握……"
L20_1.m_Talk_DEU = "Sie müssen sich noch fertig etablieren, da die Datenmenge so gigantisch ist ..."
L20_1.m_Talk_FRA = "Enfin, en partie. Le volume d'informations était trop important..."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE2_START@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 3900305
