L22_1 = {}
L23_1 = 1.3
L24_1 = 1.3
L22_1[1] = L23_1
L22_1[2] = L24_1
L21_1.m_CharScale = L22_1
L21_1.m_CharScaleTime = 0.01
L21_1.m_Talk_KOREA = "기억은 인간을 구분하는 중요한 요소이니, 나도 우리 아빠를……."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "記憶は人間を区分する重要な要素だから、私も父さんを……"
L21_1.m_Talk_ENG = "Since memory is a core part of what distinguishes a human being... it's not strange to claim..."
L21_1.m_Talk_TWN = "記憶是分辨人的其中一個要素，因此我以爸爸……"
L21_1.m_Talk_THA = "แต่ในเมื่อความทรงจำของฉันเป็นส่วนสำคัญของสิ่งที่แยกแยะมนุษย์ออกจากสิ่งอื่น... ก็แปลกหรอกถ้าจะบอกว่า..."
L21_1.m_Talk_VTN = "Vì trí nhớ là phần cốt lõi để phân biệt một con người... nên không lạ khi nói rằng..."
L21_1.m_Talk_SCN = "但记忆就是区分人类的重要因素，所以我自称为父亲……"
L21_1.m_Talk_DEU = "Erinnerungen sind ein Hauptfaktor für die Distinktion von Menschen. Also kann ich meinen Vater ..."
L21_1.m_Talk_FRA = "La mémoire est un indicateur infaillible qui permet de distinguer un humain d'un autre..."
L22_1 = {}
