L23_1 = {}
L24_1 = 1.3
L25_1 = 1.3
L23_1[1] = L24_1
L23_1[2] = L25_1
L22_1.m_CharScale = L23_1
L22_1.m_CharScaleTime = 0.01
L22_1.m_Crash = 10
L22_1.m_Talk_KOREA = "아니, 죽은 알파트릭스의 회장을 자처해도 이상하지 않지."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "いや、亡きアルファトリックスの会長を自任してもおかしくないわ。"
L22_1.m_Talk_ENG = "That I am still my father, no, the late President of Alphatrix."
L22_1.m_Talk_TWN = "不對，我以死去的阿爾法崔克斯會長自居，一點也不奇怪。"
L22_1.m_Talk_THA = "ฉันยังเป็นพ่อตัวเอง ไม่สิ ประธานคนก่อนของอัลฟาทริกซ์"
L22_1.m_Talk_VTN = "Ta cũng là cha ta, không, là cố Chủ Tịch của Alphatrix."
L22_1.m_Talk_SCN = "不，自称为死去的阿尔法崔克斯会长，也没有任何问题！"
L22_1.m_Talk_DEU = "nein, den toten Vorsitzenden von Alphatrix verkörpern. Kein Problem."
L22_1.m_Talk_FRA = "Alors ce n'est pas si étrange de me voir prendre la place de mon père... Enfin, du président d'Alphatrix."
