L26_1 = {}
L26_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE2_START@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 3900305
L26_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_SERIOUS2"
L26_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L26_1.m_Pos = "L"
L26_1.m_Crash = 10
L26_1.m_Talk_KOREA = "회장은 네게 자기도 어릴 적 부모를 잃었다고 말했지?"
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "会長はあんたに自分も幼い頃両親を亡くしたと言ったわよね？"
L26_1.m_Talk_ENG = "The President told you that he lost his parents at an early age, didn’t he?"
L26_1.m_Talk_TWN = "會長是不是跟你說過，他和你一樣從小便失去父母？"
L26_1.m_Talk_THA = "ท่านประธานบอกว่าเธอเสียพ่อแม่ไปตั้งแต่ยังเด็กใช่มั้ย?"
L26_1.m_Talk_VTN = "Chủ tịch nói với mày rằng ông ấy mất cha mẹ từ nhỏ, phải không?"
L26_1.m_Talk_SCN = "会长是不是和你说过，自己在小时候就失去了父母？"
L26_1.m_Talk_DEU = "Der Vorsitzende hat dir gesagt, dass auch er als Kind seine Eltern verloren hat, ja?"
L26_1.m_Talk_FRA = "Mon père t'a dit qu'il avait perdu ses parents quand il était jeune, n'est-ce pas ?"
L27_1 = {}
L27_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE2_START@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 3900305
L27_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_SERIOUS2"
L27_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L27_1.m_Pos = "L"
L27_1.m_Talk_KOREA = "회장은 두려움에 겨워 기억을 묻어 뒀지만, 나는 알 수 있어."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "会長は恐怖に耐えきれず記憶を心の奥底にしまっていたけど、\n私にはわかるわ。"
L27_1.m_Talk_ENG = "Although he may have blocked out that memory, I still remember it."
L27_1.m_Talk_TWN = "雖然會長因為太害怕而將這段記憶埋才起來，但我還是可以知道。"
L27_1.m_Talk_THA = "ถึงเขาจะปิดกั้นความทรงจำนั้น แต่ฉันก็ยังจำได้นะ"
L27_1.m_Talk_VTN = "Mặc dù ông ấy có thể đã chặn ký ức đó, nhưng ta vẫn còn nhớ rõ."
L27_1.m_Talk_SCN = "虽然因为过于恐惧，他将那件事情埋藏到了记忆的深处，但我却知道。"
L27_1.m_Talk_DEU = "Der Vorsitzende hat seine Erinnerungen aus Furcht vergraben, doch ich weiß es."
L27_1.m_Talk_FRA = "Il a enfoui ses souvenirs parce qu'il était terrifié, mais moi je peux savoir."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE2_START@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 3900305
L28_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_SERIOUS2"
L28_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L28_1.m_Pos = "L"
L28_1.m_Crash = 10
L28_1.m_Talk_KOREA = "그건 분명 침식 재난이었어. 그 땐 관리국이 없어서 그런 용어 자체가 없었지만."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "あれは確かに侵食災害だった。\nあの時は管理局がなくて、そんな用語自体がなかったけど。"
L28_1.m_Talk_ENG = "It was a Corruption disaster. But back then, there wasn’t anything called the Administration."
L28_1.m_Talk_TWN = "是因為侵蝕災難的關係，只是當時還沒有管理局，還沒有這個說法。"
L28_1.m_Talk_THA = "มันคือภัยพิบัติคอร์รัปชั่น แต่ตอนนั้นยังไม่มีสิ่งที่เรียกว่าองค์การบริหารโลก"
L28_1.m_Talk_VTN = "Đó là một thảm họa Ăn Mòn. Nhưng hồi đó, không có cái gọi là Cục Quản Lý."
L29_1 = "那次分明就是侵蚀灾难。但因为发生在管理局创立之前，所以没有正式被命名。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Das war garantiert eine Verderbniskatastrophe. Das Wort existierte nur nicht, weil es die Administration damals nicht gab."
L28_1.m_Talk_DEU = L29_1
L29_1 = "C'était à cause d'une Sinistre de corruption. Enfin à ce moment-là, ce terme n'existait pas encore puisque l'Administration n'avait pas encore été fondée."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "ALPHA_ACT3_STAGE2_START@29#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 29
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3900305
L29_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L29_1.m_Pos = "R"
L30_1 = "그 이야기는……. 고모님은 정말로 할아버님의 기억을……."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "その話は……叔母様は本当にお祖父様の記憶を……"
L29_1.m_Talk_JPN = L30_1
L30_1 = "The story... So you really do have his memories..."
L29_1.m_Talk_ENG = L30_1
L30_1 = "姑姑……真的將爺爺的記憶……"
L29_1.m_Talk_TWN = L30_1
L30_1 = "เรื่องนั้น... คุณมีความทรงจำของท่านจริงๆ สินะคะ..."
L29_1.m_Talk_THA = L30_1
L30_1 = "Câu chuyện... Vậy ra, cô thực sự có ký ức của ông ấy..."
L29_1.m_Talk_VTN = L30_1
L30_1 = "那就是说……姑姑真的有爷爷的记忆……"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Das heißt ... dass Sie wirklich die Erinnerungen Großvaters ..."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Cela veut dire que... Vous avez vraiment récupéré la mémoire de grand-père..."
L29_1.m_Talk_FRA = L30_1
