L32_1 = "ALPHA_ACT3_STAGE2_START@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3900305
L31_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_SERIOUS2"
L31_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L31_1.m_Pos = "C"
L31_1.m_Crash = 10
L32_1 = "원인 모를 괴생명체의 습격에서 살아남은 뒤로 회장은 변했어."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "得体の知れない怪生命体の襲撃から生き延びた後、会長は変わった。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "He changed after surviving an attack from an unknown monster."
L31_1.m_Talk_ENG = L32_1
L32_1 = "當他從奇怪生物的攻擊中倖存下來後，他整個人都變了。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เขาเปลี่ยนไปหลังรอดจากการจู่โจมของสัตว์ประหลาดลึกลับ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Ông ấy đã thay đổi sau khi sống sót từ vụ bị một con quái vật vô danh tấn công."
L31_1.m_Talk_VTN = L32_1
L32_1 = "在被未知的生命体袭击并生存下来后，会长就变了。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Nachdem er den Übergriff der unerklärlichen Monsterwesen überlebt hatte, veränderte sich der Vorsitzende."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Après avoir survécu à cette attaque, mon père a changé."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "ALPHA_ACT3_STAGE2_START@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3900305
L32_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_SERIOUS2"
L32_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L32_1.m_Pos = "C"
L33_1 = "세상을 몰랐기에 두려워할 필요도, 걱정할 필요도 없던 자신의 어린 시절처럼……"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "世間を知らなかったから恐れる必要も心配する必要もなかった\n自身の子ども時代のように……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "He devoted his entire life to making the world a better place..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "他將他的一生都用來打造一個不需要害怕，也不需要擔心的世界…"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เขาอุทิศชีวิตให้กับการทำให้โลกดีขึ้น..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Ông ấy đã cống hiến toàn bộ cuộc đời mình để làm cho thế giới trở nên tốt đẹp hơn..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "他为了找回那个对未知世界无所畏惧，无忧无虑的童年……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Er kannte die Welt noch nicht und kannte deshalb keine Furcht, und brauchte auch keine Furcht, wie in seiner Kindheit ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Il voulait... créer un monde meilleur."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "ALPHA_ACT3_STAGE2_START@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3900305
L33_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_SERIOUS2"
L33_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L33_1.m_Pos = "C"
L34_1 = "더 나은 세상을 만드는 데 평생을 매달렸지."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "より良い世界を作ることに一生をかけた。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Just as how it was when he was a child... When he had nothing to fear or worry about."
L33_1.m_Talk_ENG = L34_1
L34_1 = "就像他小時候認識的那個世界一樣。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เหมือนตอนที่เขายังเป็นเด็ก... ที่ไม่มีอะไรให้ต้องกลัวหรือกังวล"
L33_1.m_Talk_THA = L34_1
L34_1 = "Giống như khi ông ấy còn là một đứa trẻ... Khi ông ấy không có gì phải sợ hãi hay lo lắng nữa."
L33_1.m_Talk_VTN = L34_1
L34_1 = "为了创造更加美好的世界……而终身奋斗。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Und er widmete sein Leben einer besseren Welt ..."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Un monde sans crainte ni inquiétudes, comme durant son enfance..."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
