L36_1 = {}
L37_1 = "ALPHA_ACT3_STAGE2_START@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3900305
L36_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_SERIOUS2"
L36_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L36_1.m_Pos = "L"
L37_1 = "그 때부터 돈을 모으기 시작한 거야. 인간으로는 삼류 쓰레기지만, 돈 버는 재주는 남달랐으니까."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "あの時から金を集め始めたのよ。人間としては三流のゴミ同然だけど、\n儲ける才能は並み外れていたからね。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "That’s when he started to save up money. He was a scumbag, but he did have a gift for making himself rich."
L36_1.m_Talk_ENG = L37_1
L37_1 = "他就是從那時候開始拼命賺錢的，身為一個人他不過就是個垃圾，但他確實非常會賺錢！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ตอนนั้นแหละที่เขาเริ่มเก็บเงิน เขาอาจเป็นเศษสวะ แต่ก็มีพรสวรรค์ด้านสร้างความร่ำรวยให้ตัวเอง"
L36_1.m_Talk_THA = L37_1
L37_1 = "Đó là lúc ông ấy bắt đầu tiết kiệm tiền. Ông ta là một tên chó má, nhưng ông ta có năng khiếu kiếm tiền kỳ lạ."
L36_1.m_Talk_VTN = L37_1
L37_1 = "也为此开始攒钱。哪怕他做人很失败，但赚钱的本事却很厉害。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ab dem Zeitpunkt baute er sich ein Vermögen auf. Als Mensch war er Abschaum, aber im Geldverdienen war er unvergleichlich."
L36_1.m_Talk_DEU = L37_1
L37_1 = "C'est à ce moment-là qu'il a commencé à planifier son projet. C'était peut-être une ordure, mais il était très doué en affaire."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "ALPHA_ACT3_STAGE2_START@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3900305
L37_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_SERIOUS2"
L37_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L37_1.m_Pos = "L"
L38_1 = "경쟁 기업을 무너뜨리고, 직원들을 죽을 만큼 혹사시키고, 자기 아내와 자식들까지 돈벌이에 이용하면서……."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ライバル企業を倒産させ、従業員たちを死ぬほど酷使して、\n自分の妻や子どもたちまで金儲けに利用してまで……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "He took out competitors, treated his employees like tools, and even used his wife and child as a source of income..."
L37_1.m_Talk_ENG = L38_1
L38_1 = "不只打垮競爭對手，讓員工們做得要死，還利用自己的妻子和小孩賺錢……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เขากำจัดคู่แข่ง เห็นพนักงานเป็นเครื่องมือ แล้วก็ถึงขั้นใช้ลูกใช้เมียเป็นแหล่งรายได้"
L37_1.m_Talk_THA = L38_1
L38_1 = "Ông ta hạ gục đối thủ cạnh tranh, đối xử với nhân viên của mình như công cụ, và thậm chí sử dụng vợ con mình như một nguồn thu nhập..."
L37_1.m_Talk_VTN = L38_1
L38_1 = "他打垮了很多竞争企业，把职员们当牲畜一样对待，为了钱，甚至可以利用自己的妻子和孩子……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Er ruinierte Konkurrenzunternehmen, ließ seine Mitarbeiter zu Tode schuften und nutzte sogar seine Frau und Kinder aus, um Geld zu scheffeln ..."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Il était prêt à anéantir ses concurrents, à surmener ses employés, d'utiliser sa femme et ses enfants pour gagner de l'argent..."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "ALPHA_ACT3_STAGE2_START@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3900305
L38_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_SERIOUS2"
L38_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L38_1.m_Pos = "L"
L39_1 = "하지만 그 인간에게는 처음부터 무리였어. 바꿔 말하면 돈 버는 재주밖에 없었거든."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "でも、あいつには最初から無理だった。言い換えれば、金を稼ぐ才能しかなかったのよ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But it was doomed from the start. In other words, his only skill was making money."
L38_1.m_Talk_ENG = L39_1
L39_1 = "但他根本從一開始就辦不到，換句話說，他就只會賺錢而已。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แต่มันพินาศตั้งแต่ต้นแล้ว หรือก็คือ เขามีปัญญาแค่หาเงินเท่านั้น"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nhưng ngay từ đầu, tất cả đã là sai lầm. Nói cách khác, kỹ năng duy nhất của ông ta là kiếm tiền."
L38_1.m_Talk_VTN = L39_1
L39_1 = "但对他来说，梦想根本没有实现的可能性。因为他只会赚钱。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Aber er hatte sich zu viel vorgenommen. Denn anders gesagt hatte er kein anderes Talent als das Geldverdienen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Mais enfin c'était perdu d'avance. Un monde meilleur, alors que lui-même ne connaissait que l'argent ? Pff."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
