L41_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L41_1.m_Pos = "C"
L41_1.m_Crash = 10
L42_1 = "회장은 널 소중히 여긴 게 아냐."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "会長はあんたを大切にしていたわけじゃない。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "The President didn’t think of you as special."
L41_1.m_Talk_ENG = L42_1
L42_1 = "會長並不是看重你，"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ประธานน่ะไม่ได้เห็นว่าเธอวิเศษวิโสอะไรหรอก"
L41_1.m_Talk_THA = L42_1
L42_1 = "Chủ Tịch không hề thấy mày đặc biệt."
L41_1.m_Talk_VTN = L42_1
L42_1 = "会长并不爱你。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Der Vorsitzende hat dich nicht wertgeschätzt."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Mon père ne s'est jamais préoccupé de toi."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "ALPHA_ACT3_STAGE2_START@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3900305
L42_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_SERIOUS2"
L42_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L42_1.m_Pos = "C"
L42_1.m_Crash = 20
L43_1 = "그저 자기 미련을 대신 이뤄 줄 누군가가 필요했을 뿐이지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ただ、自分の未練を代わりに叶えてくれる誰かが必要だっただけなのよ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "He just saw you as a means to achieve his unfulfilled dreams."
L42_1.m_Talk_ENG = L43_1
L43_1 = "他只是需要一個，能夠代替他達成心願的對象而已。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เขาก็เห็นเธอเป็นเครื่องมือในการบรรลุฝันที่ยังไม่เป็นจริงเท่านั้น"
L42_1.m_Talk_THA = L43_1
L43_1 = "Ông ta chỉ xem mày là công cụ để hoàn thành những giấc mơ mà ông ta không thể đạt được."
L42_1.m_Talk_VTN = L43_1
L43_1 = "只是需要有人替他完成他的梦想。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Er brauchte nur jemanden, der seine falschen Hoffnungen an seiner Stelle erfüllt."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Il avait juste besoin que quelqu'un réalise son rêve à sa place."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
