L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3900305
L49_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
