L49_1.m_Face = "UNIT_SURPRISE"
L49_1.m_CharStrID = "SEAROM_ALPHA_NULL_NULL"
L49_1.m_Pos = "L"
L50_1 = "쟤들……! 리더랑 얼굴이 똑같아!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "あの子たち…！　リーダーと同じ顔をしてる！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Look...! Those things all look like Leader!"
L49_1.m_Talk_ENG = L50_1
L50_1 = "他們……！長得都和老大一模一樣！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ดูสิ...! พวกนั้นเหมือนท่านผู้นำเลย!"
L49_1.m_Talk_THA = L50_1
L50_1 = "Xem kìa...! Những thứ đó đều giống hệt Thủ Lĩnh!"
L49_1.m_Talk_VTN = L50_1
L50_1 = "她们……！和队长的脸完全一样！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Die da ...! Sie sehen genauso aus wie die Anführerin!"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Regardez...! Elles ressemblent toutes à la chef !"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "ALPHA_ACT3_STAGE2_START@50#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3900305
L50_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_Face = "UNIT_SERIOUS"
L50_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L50_1.m_Pos = "R"
L51_1 = "응. 저것들이 그 클론인가 봐."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "そうですね。あれが例のクローンでしょうか。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Uh-huh. I’m guessing those are the clones."
L50_1.m_Talk_ENG = L51_1
L51_1 = "嗯，他們應該都是複製人。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "อือฮึ ฉันว่าพวกนั้นคือร่างโคลนนะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Vậy đó là những bản sao."
L50_1.m_Talk_VTN = L51_1
L51_1 = "嗯。她们就是克隆体吧。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Stimmt. Das müssen die Klone sein."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Oui. Ce sont sûrement des clones."
L50_1.m_Talk_FRA = L51_1
