L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 51
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3900305
L1_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
