L1_1.m_Pos = "R"
L2_1 = "전부 밸런스 브레이커로 무장하고 있어. 너도 평소처럼 튀어나가면 벌집이 될 거야."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "全員バランスブレイカーで武装しています。\nアサネ、いつもどおりに飛び出したらハチの巣にされますよ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "They’re all equipped with Balance Breakers. Watch out, or you’ll become Swiss cheese."
L1_1.m_Talk_ENG = L2_1
L2_1 = "他們全都有裝載平衡破壞者，你再跟平時一樣輕舉妄動很可能會變成蜂窩。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "มีผู้ทำลายสมดุลกันทุกตัวเลย ระวังนะ ไม่งั้นพรุนเป็นชีสแน่"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tất cả chúng đều được trang bị Balance Breakers. Coi chừng, nếu không cô sẽ trở thành pho mát Thụy Sĩ mất."
L1_1.m_Talk_VTN = L2_1
L2_1 = "全都用平衡破坏者武装起来了。如果你像平时那样冲过去，一定会被打成马蜂窝。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Sie sind alle mit Balancebrechern ausgestattet. Wenn du dich auf sie stürzt wie sonst auch, wirst du durchlöchert."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Elles ont toutes des Briseurs d'équilibre. Au moindre geste brusque, tu risques d'être criblée de balles."
L1_1.m_Talk_FRA = L2_1
