L8_1 = "ALPHA_ACT3_STAGE2_START@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3900305
L7_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_SERIOUS2"
L7_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L7_1.m_Pos = "C"
L8_1 = "네가 하나 틀린 게 있어. 신지아."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "あんたは一つ間違っているわ、ヒメノ・ユイ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You’re wrong about one thing, Shin Jia."
L7_1.m_Talk_ENG = L8_1
L8_1 = "沈佳，你弄錯一件事。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แต่เธอผิดไปเรื่องนึงนะเฉิน เจีย"
L7_1.m_Talk_THA = L8_1
L8_1 = "Mày đã sai về một điều, Shin Jia."
L7_1.m_Talk_VTN = L8_1
L8_1 = "有一点你错了。沈佳。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Du hattest in Einem unrecht, Jia."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Mais tu t'es trompée sur un point, Jia."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "ALPHA_ACT3_STAGE2_START@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3900305
L8_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_SERIOUS2"
L8_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L8_1.m_Pos = "C"
L9_1 = "여기 있는 것들은 모두 회장이 폐기했던…… 나와 같은 실패작들이야."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ここにあるモノはすべて会長が廃棄した……私と同じ失敗作よ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Everything here was discarded by the President... They’re all failed projects, just like me."
L8_1.m_Talk_ENG = L9_1
L9_1 = "現在在場的全都是會長不要的……和我一樣是個失敗品。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ประธานทิ้งทุกอย่างที่นี่ไปนะ... โครงการพวกเขาล้มเหลว เหมือนฉันนี่แหละ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tất cả bọn chúng đều bị Chủ Tịch vứt bỏ... Tất cả đều là những dự án thất bại, giống như ta vậy."
L8_1.m_Talk_VTN = L9_1
L9_1 = "在这里的这些克隆体，都是会长废弃的……和我一样的失败品。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Alle die hier wurden vom Vorsitzenden entsorgt ... Sie sind Fehlschläge, so wie ich."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Tout ce que tu vois ici, moi comprise, ce sont les résultats des expériences ratées de mon père..."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "ALPHA_ACT3_STAGE2_START@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3900305
L9_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_SERIOUS2"
L9_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L9_1.m_Pos = "C"
L10_1 = "가능성을 인정 받은 단 하나의 개체를 제외하곤 말이지."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "可能性を認められた、たった一体の個体を除いてね。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Well, all except for one unit."
L9_1.m_Talk_ENG = L10_1
L10_1 = "當然不包括那唯一一個，可能性受到肯定的個體。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ล้มเหลวหมด ยกเว้นยูนิตหนึ่ง"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đúng, tất cả ngoại trừ một đơn vị."
L9_1.m_Talk_VTN = L10_1
L10_1 = "只有一个是被他认可的有着无限可能的唯一个体。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Außer einer einzigen Einheit, deren Potenzial anerkannt wurde."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Tout, à l'exception d'une personne."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
