L12_1 = "ALPHA_ACT3_STAGE2_START@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3900305
L11_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_HATE"
L11_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L11_1.m_Pos = "C"
L11_1.m_Crash = 10
L12_1 = "그 개체가……. 저군요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "その個体が……私だったのですね。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I assume that’s me..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "那個個體……就是我吧？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เดาว่าคือฉันสินะคะ..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Cháu cho rằng đó là cháu..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "那个个体……是我吧。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Diese Einheit ... bin ich."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Et l'exception, c'est... moi, n'est-ce pas ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "ALPHA_ACT3_STAGE2_START@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3900305
L12_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_SERIOUS"
L12_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_04"
L12_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L13_1 = "R_M_I"
L12_1.m_Pos = L13_1
L13_1 = "리더, 대치 중입니다. 적의 말에 귀 기울이지 마세요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "リーダー、対峙中です。敵の発言に耳を傾ける必要はありません。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Leader, we’re in position. Don’t listen to her lies."
L12_1.m_Talk_ENG = L13_1
L13_1 = "老大，現在在對峙中，千萬不能受敵人的話影響！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ท่านผู้นำ เราประจำตำแหน่งแล้ว อย่าไปฟังคำโกหกเธอนะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Thủ Lĩnh, chúng tôi đã vào vị trí. Đừng nghe cô ta nói xàm."
L12_1.m_Talk_VTN = L13_1
L13_1 = "队长，我们已经就位。动手吧，别听她胡说。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Anführerin, wir befinden uns in Konfrontation. Hören Sie nicht auf den Feind."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Nous sommes en plein combat, il ne faut pas croire ce que dit l'ennemi."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "ALPHA_ACT3_STAGE2_START@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3900305
L13_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "아뇨. 혁신의 밤 전날에 봤어요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "いいえ。革新の夕べの前日に見ました。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "No, I saw them the day before the Night of Innovation."
L13_1.m_Talk_ENG = L14_1
L14_1 = "不是的，在革新之夜的前一天我有看到。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ไม่ค่ะ ฉันเคยเห็นพวกนั้นมาแล้วตอนงานราตรีของอินโนเวชั่น"
L13_1.m_Talk_THA = L14_1
L14_1 = "Không, tôi đã nhìn thấy họ một ngày trước Đêm Cải Cách."
L13_1.m_Talk_VTN = L14_1
L14_1 = "不。我在革新之夜的前一天见到过她们。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Nein, ich habe es am Tag vor der revolutionären Nacht gesehen."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Non, je l'ai vu la veille de la soirée de l'Innovation."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "ALPHA_ACT3_STAGE2_START@64#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 64
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3900305
L14_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L14_1.m_Pos = "C"
L15_1 = "여기와 비슷한 풍경에 소독약 냄새, 그리고 할아버님의 목소리……."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "ここと似た風景に消毒薬の臭い、そしてお祖父様の声……"
L14_1.m_Talk_JPN = L15_1
L15_1 = "A place similar to this with a faint smell of antiseptics, and Grandfather’s voice..."
L14_1.m_Talk_ENG = L15_1
L15_1 = "和這裡類似的景象，加上消毒水的味道，還有爺爺的聲音……"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ที่ที่คล้ายกันนี้กับกลิ่นยาฆ่าเชื้อจางๆ แล้วก็เสียงของคุณปู่..."
L14_1.m_Talk_THA = L15_1
L15_1 = "Một nơi tương tự như thế này với mùi thuốc sát trùng thoang thoảng, và giọng nói của ông nội..."
L14_1.m_Talk_VTN = L15_1
L15_1 = "和这里差不多的风景，消毒药水的味道，还有爷爷的声音……"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Eine Umgebung wie hier, der Geruch von Desinfektion und Großvaters Stimme ..."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Cette salle où nous sommes... Cette odeur de désinfectant et la voix de grand-père..."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
