L18_1.m_Crash = 10
L19_1 = "회장은 널 애지중지했지."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "会長はあんたを大事にしてたわね。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "The President cared about you deeply."
L18_1.m_Talk_ENG = L19_1
L19_1 = "會長非常疼愛你對吧？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ท่านประธานน่ะใส่ใจเธอมากนะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Chủ Tịch quan tâm mày từ tận đáy lòng."
L18_1.m_Talk_VTN = L19_1
L19_1 = "会长一直对你宠爱有加。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Der Vorsitzende hat dich geliebt."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Le président t'aimait beaucoup."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "ALPHA_ACT3_STAGE2_START@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3900305
L19_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_SERIOUS2"
L19_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L19_1.m_Pos = "C"
L20_1 = "하지만 결국 그건 네가 말 잘 듣고 유능한 기물이었기 때문이야."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "でも結局、それはあんたが言うことをよく聞いてくれる有能な駒だったからよ。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "But that was because you were an obedient and powerful pawn of his."
L19_1.m_Talk_ENG = L20_1
L20_1 = "但那也只不過是因為，你是一顆聽話又能幹的棋子。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "แต่นั้นก็เพราะเธอเป็นตัวหมากที่ว่านอนสอนง่ายและทรงพลังของเขาไง"
L19_1.m_Talk_THA = L20_1
L20_1 = "Nhưng đó là bởi vì mày là một con tốt ngoan ngoãn và mạnh mẽ."
L19_1.m_Talk_VTN = L20_1
L20_1 = "但归根结底，也只是因为你是个听话的棋子而已。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Aber nur, weil du letztendlich eine Schachfigur warst, die ihm gehorcht und fähig ist."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Mais c'est surtout parce que tu étais une pièce à son service."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "ALPHA_ACT3_STAGE2_START@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3900305
L20_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_SERIOUS2"
L20_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L20_1.m_Pos = "C"
L21_1 = "자기 뜻 따위는 없고, 말하는 대로 따르기만 하는."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "自分の意志なんかない、言う通りに従うだけの。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "You have no self-meaning, and only do as you’re told."
L20_1.m_Talk_ENG = L21_1
L21_1 = "沒有自己的主見，只會聽命行事。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เธอไม่มีความหมายอะไรในตัวเอง ดีแต่ทำตามที่คนอื่นบอก"
L20_1.m_Talk_THA = L21_1
L21_1 = "Mày không có sự ích kỷ và chỉ biết tuân lệnh."
L20_1.m_Talk_VTN = L21_1
L21_1 = "你没有自身的意志，只会按照他说过的话行动。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ohne eigenen Willen und hörig aufs Wort."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Un pion sans conscience, qui ne faisait qu'exécuter les ordres."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "ALPHA_ACT3_STAGE2_START@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3900305
L21_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_SERIOUS2"
L21_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L21_1.m_Pos = "C"
L22_1 = 50
L21_1.m_Crash = L22_1
L22_1 = "그 인간에게는! 그 쓰레기에게는 결국 너도 자기 망상을 이뤄 줄 수단에 불과했다고!"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "あいつには！　あのクズには結局あんたも自分の妄想を叶える手段に\nすぎなかったのよ！"
L21_1.m_Talk_JPN = L22_1
L22_1 = "To him! That piece of trash saw you as a means to his end!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "對那個人！對那個垃圾而言，你不過就是能替他完成幻想的工具！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "สำหรับเขา! เศษสวะนั่นเห็นเธอเป็นแค่วิธีไปสู่ผลลัพธ์เท่านั้นแหละ!"
L21_1.m_Talk_THA = L22_1
L22_1 = "Với ông ta! Cái thứ rác rưởi đó đã coi mày như một phương tiện cho tới cuối đời!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "对那个人来说！对那个垃圾来说，你不过是实现他妄想的手段而已！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Für ihn, für diesen Abschaum, warst du nur ein Mittel zum Zweck, um seine Wahnvorstellungen zu erfüllen!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Pour l'ordure qu'il était, tu étais l'invention qui allait réaliser son rêve !"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
