L24_1 = "ALPHA_ACT3_STAGE2_START@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3900305
L23_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "……아뇨. 고모님은 모르고 계세요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "……いいえ。叔母様にはわからないでしょう。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "No, Auntie... You’re wrong."
L23_1.m_Talk_ENG = L24_1
L24_1 = "……不是的，姑姑你不知道。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ไม่ค่ะ... น้าเข้าใจผิดแล้ว"
L23_1.m_Talk_THA = L24_1
L24_1 = "Không, cô... cô nhầm rồi."
L23_1.m_Talk_VTN = L24_1
L24_1 = "……不。姑姑你不知道。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "... Nein. Tante, Sie haben keine Ahnung."
L23_1.m_Talk_DEU = L24_1
L24_1 = "... Non, je crois que vous ne comprenez pas."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
