L25_1 = "UNIT_PRIDE"
L24_1.m_Face = L25_1
L25_1 = "THMEA_SAD_01"
L24_1.m_StartBGMFileName = L25_1
L24_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L24_1.m_Pos = "C"
L25_1 = "할아버님은 절 아껴 주셨어요. 진심으로."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "お祖父様は私を大切にしてくれました。心から。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Grandfather loved me with all his heart."
L24_1.m_Talk_ENG = L25_1
L25_1 = "爺爺是真心在疼愛我的。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "คุณปู่รักหนูหมดหัวใจค่ะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Ông nội yêu cháu bằng cả trái tim."
L24_1.m_Talk_VTN = L25_1
L25_1 = "爷爷非常爱我。是真心的。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Großvater hat mich geliebt. Von ganzem Herzen."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Grand-père tenait beaucoup à moi. Sincèrement."
L24_1.m_Talk_FRA = L25_1
