L31_1 = "ALPHA_ACT3_STAGE2_START@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3900305
L30_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
