L30_1.m_fWaitTime = 0
L31_1 = "CEO_NPC_ALPHA_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "내가……. 그 아이에게 너무…… 큰 잘못을……."
L30_1.m_Talk_KOREA = L31_1
L31_1 = 0.05
L30_1.m_fTalkTime = L31_1
L31_1 = "私は……あの子にあまりにも……大きな過ちを……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I... big mistake... to her..."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我……對那孩子……犯下很嚴重的錯誤……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ผม... ผิดใหญ่หลวง... กับเธอ..."
L30_1.m_Talk_THA = L31_1
L31_1 = "Ta... sai lầm lớn... với con bé..."
L30_1.m_Talk_VTN = L31_1
L31_1 = "我……对那个孩子……犯下了……不可饶恕的错……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich habe ... zu viel gegen das Kind ... verbrochen ..."
L30_1.m_Talk_DEU = L31_1
L31_1 = "J'ai... fais du mal... à cet enfant..."
L30_1.m_Talk_FRA = L31_1
