L32_1 = "ALPHA_ACT3_STAGE2_START@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3900305
L31_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "CEO_NPC_ALPHA_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "그런데도……. 그 아이는……. 나만……."
L31_1.m_Talk_KOREA = L32_1
L32_1 = 0.05
L31_1.m_fTalkTime = L32_1
L32_1 = "それでも……あの子は……私だけを……"
L31_1.m_Talk_JPN = L32_1
L32_1 = "But she... still... only me..."
L31_1.m_Talk_ENG = L32_1
L32_1 = "但……那孩子……對我……"
L31_1.m_Talk_TWN = L32_1
L32_1 = "แต่เธอ... ก็ยัง... แค่ผม..."
L31_1.m_Talk_THA = L32_1
L32_1 = "Nhưng con bé... vẫn... chỉ có ta..."
L31_1.m_Talk_VTN = L32_1
L32_1 = "可是……那个孩子……却对我……"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Und trotzdem ... hat es ... nur mich ..."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Mais... Elle reste... avec moi..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
