L34_1 = 1.5
L35_1 = 1.5
L33_1[1] = L34_1
L33_1[2] = L35_1
L32_1.m_CharScale = L33_1
L32_1.m_CharScaleTime = 0.01
L33_1 = 50
L32_1.m_Crash = L33_1
L33_1 = "웃기지 마! 대체 뭘 믿고 그딴 헛소리를 지껄여!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ふざけるな！　いったい何を根拠にそんなうわごとが言えるの！？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Nonsense! You must be insane to think that!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "笑死人！你憑什麼在那邊胡說八道！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เหลวไหล! เธอมันบ้าแล้วที่คิดแบบนั้น!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Vô lý! Mày quá điên khi nghĩ như vậy!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "不准笑！你有什么依据吗！胡说八道！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Lächerlich! Woher nimmst du dir so einen Schwachsinn heraus?!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Non mais qu'est-ce qui te fait croire une chose pareille ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "ALPHA_ACT3_STAGE2_START@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3900305
L33_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_SERIOUS"
L33_1.m_CharStrID = "JIA_ALPHA_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "그리고 저는, 할아버님의 수단이 아니에요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "そして私は、お祖父様の駒ではありません。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Also, I wasn’t a means to his end."
L33_1.m_Talk_ENG = L34_1
L34_1 = "而且我並不是爺爺的工具。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "และฉันก็ไม่ใช่วิธีที่นำไปสู่ผลลัพธ์ของท่านด้วยค่ะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Ngoài ra, cháu không phải là một phương tiện cho đến cuối đời của ông ấy."
L33_1.m_Talk_VTN = L34_1
L34_1 = "还有我，不是爷爷的棋子。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Außerdem bin ich kein Mittel zum Zweck für meinen Großvater."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je ne suis pas la marionnette de grand-père."
L33_1.m_Talk_FRA = L34_1
