L36_1 = "두려워할 필요도, 걱정할 필요도 없는 세상을 만들 수 있다면."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "恐れる必要も、心配する必要もない世界を作ることができるのなら。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Make the world a place without fear or worries..."
L35_1.m_Talk_ENG = L36_1
L36_1 = "我在乎的人都不需要害怕或擔心的世界，"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ทำให้โลกใบนี้เป็นที่ที่ปราศจากความกลัวและความกังวลได้..."
L35_1.m_Talk_THA = L36_1
L36_1 = "Biến thế giới thành một nơi không còn sợ hãi hay lo lắng..."
L35_1.m_Talk_VTN = L36_1
L36_1 = "如果能创造没有恐惧，没有担忧的世界。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "in einer Welt leben können, ohne Furcht und Sorge,"
L35_1.m_Talk_DEU = L36_1
L36_1 = "les gens qui me sont chers puissent vivre sans aucune crainte et inquiétude"
L35_1.m_Talk_FRA = L36_1
