L38_1 = "할아버님이 아니라, 제 의지로요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "お祖父様ではなく、私の意志で。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Not because Grandfather told me to, but of my own will."
L37_1.m_Talk_ENG = L38_1
L38_1 = "不是因為爺爺，而是我自己想這麼做！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ไม่ใช่เพราะคุณปู่บอกให้ทำนะคะ แต่ด้วยเจตจำนงของฉันเอง"
L37_1.m_Talk_THA = L38_1
L38_1 = "Không phải vì ông nội bảo vậy, mà là do ý muốn của cháu."
L37_1.m_Talk_VTN = L38_1
L38_1 = "不是因为爷爷的遗愿，而是我自己的意志。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Nicht aus Großvaters, sondern aus meinem Willen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Et ça c'est ma volonté, pas celui de grand-père."
L37_1.m_Talk_FRA = L38_1
