L44_1 = "아빠, 내 머릿속에서 잘 듣고 있어?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "父さん、私の頭の中で今の話を聞いてる？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Daddy, did you hear that?!"
L43_1.m_Talk_ENG = L44_1
L44_1 = "爸，你在我腦袋裡有聽到嗎？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "พ่อคะ ได้ยินมั้ย?!"
L43_1.m_Talk_THA = L44_1
L44_1 = "Cha ơi, Cha có nghe thấy không?!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "父亲，你听到了吗？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Papa, hörst du mich in meinem Kopf?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Papa, t'entends ce qu'elle dit ?"
L43_1.m_Talk_FRA = L44_1
