L45_1 = "ALPHA_ACT3_STAGE2_START@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3900305
L44_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_SERIOUS2"
L44_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L44_1.m_Pos = "C"
L45_1 = "아빠는 성공했네! 이렇게 말 잘 듣는 손녀를 뒀으니까!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "父さんは成功したね！　こんなに言うことをちゃんと聞く孫娘がいるんだから！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You were successful! Look how well your granddaughter actually listens to you!!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "爸你成功咧！有一個這麼聽話的孫女！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "พ่อทำสำเร็จแล้วนะคะ! ดูสิว่าหลานพ่อเชื่อฟังคำพ่อขนาดไหน!!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cha đã thành công! Hãy nhìn xem đứa cháu gái thực ngoan ngoãn nghe lời này đi!!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "父亲你成功了！你的孙女到现在还那么听你的话！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Du hattest Erfolg, Papa! Denn deine Enkelin ist dir völlig ergeben!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Tu as réussi ! Tu as une jolie petite femme qui t'obéit !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "ALPHA_ACT3_STAGE2_START@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3900305
L45_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
