L45_1.m_Pos = "C"
L46_1 = "그런데 지아야, 이를 어쩌나?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "でもね、ユイちゃん。とても残念だわ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "But Jia, I’m sorry to tell you this."
L45_1.m_Talk_ENG = L46_1
L46_1 = "可是小佳，怎麼辦呢？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แต่ว่านะเจีย ขอโทษที่ต้องบอกอย่างนี้"
L45_1.m_Talk_THA = L46_1
L46_1 = "Nhưng Jia, tao rất tiếc phải nói với mày điều này."
L45_1.m_Talk_VTN = L46_1
L46_1 = "可是小佳，该怎么办呢？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Aber Jia, ich mache dir einen Strich durch die Rechnung."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Quel dommage, Jia."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "ALPHA_ACT3_STAGE2_START@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3900305
L46_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_SERIOUS2"
L46_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L46_1.m_Pos = "C"
L47_1 = "나는 오늘 네 모든 걸 빼앗아 갈 각오로 왔거든."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "私は今日、あんたのすべてを奪う覚悟で来たのよ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I came here determined to take everything you have and more."
L46_1.m_Talk_ENG = L47_1
L47_1 = "我今天可是下定決心要奪走你的一切！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ฉันมาด้วยความมุ่งมั่นจะชิงทุกอย่างที่เธอมีและอย่างอื่นด้วย"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tao đến đây quyết tâm lấy đi tất cả những gì mày có và hơn thế nữa."
L46_1.m_Talk_VTN = L47_1
L47_1 = "我今天能走到这一步，可是已经做好了抢走你的一切的准备。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich bin nämlich hier mit dem Ziel, dir dein Alles zu nehmen."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Aujourd'hui, je suis venue récupérer tout ce que j'ai perdu."
L46_1.m_Talk_FRA = L47_1
