L49_1 = "……고모님에 대해선 저도 안타깝지만, 뜻대로 하시게 놔둘 수는 없어요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "……叔母様についてはお気の毒に思いますが、\n思いどおりにさせるわけにはいきません。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I’m also sorry, but I won’t allow you to do that."
L48_1.m_Talk_ENG = L49_1
L49_1 = "……姑姑的事我也很遺憾，但我無法讓你稱心如意。"
