L16_1 = "จะควบคุมการทดลองของท่านประธานได้ต้องมีสองเงื่อนไขนะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Có hai yêu cầu để kiểm soát các thí nghiệm của Chủ Tịch."
L15_1.m_Talk_VTN = L16_1
L16_1 = "要操控会长制造的实验体，需要满足两个要求。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Um ein Testsubjekt zu steuern, das der Vorsitzende erschaffen hat, braucht man zweierlei."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Il faut deux choses pour pouvoir manipuler un spécimen créé par mon père."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
