L17_1 = "하나는 회장 본인의 목소리. 그리고 두 번째는 지시를 입력하기 위한 명령어지."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "一つ目は会長本人の声。そして二つ目は指示を入力するためのコマンド。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "One is his voice... And the other is a trigger phrase."
L16_1.m_Talk_ENG = L17_1
L17_1 = "一是會長本人的聲音，二是下命令的指令。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "หนึ่งคือเสียงของเขา... อีกหนึ่งคือวลีกระตุ้น"
L16_1.m_Talk_THA = L17_1
L17_1 = "Một là giọng nói của ông ta... Và một là cụm từ kích hoạt."
L16_1.m_Talk_VTN = L17_1
L17_1 = "第一个条件是会长的声音。还有第二个条件就是说出特定的暗示。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Erstens die Stimme des Vorsitzenden selbst. Zweitens die Befehlsworte, um Anweisungen einzugeben."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Premièrement, la voix de mon père et deuxièmement, un ordre d'exécution pour qu'il passe à l'action."
L16_1.m_Talk_FRA = L17_1
