L22_1.m_Pos = "C"
L23_1 = "성공한 케이스라 그런가? 꽤 저항하는데?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "成功したケースだからかしら？　なかなか抵抗するじゃない。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Wow, you’re resisting? I guess you really are different from the rest."
L22_1.m_Talk_ENG = L23_1
L23_1 = "因為你是成功案例嗎？滿能忍的嘛？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "โอ้โห ขัดขืนอยู่เหรอ? ท่าทางเธอจะต่างจากตัวอื่นๆ จริงๆ นะนี่"
L22_1.m_Talk_THA = L23_1
L23_1 = "Wow, mày đang phản kháng sao? Tao đoán mày thực sự khác biệt so với những đứa khác."
L22_1.m_Talk_VTN = L23_1
L23_1 = "因为是成功的完成品，所以抵抗比想象中来得激烈吗？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Du bist wohl durchaus ein erfolgreiches Subjekt, so wie du Widerstand leistest!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Tu résistes plutôt bien ? Sûrement parce que tu es un cas d'expérience réussi."
L22_1.m_Talk_FRA = L23_1
