L29_1 = "동생이여, 알겠나! 필멸의 악이란 이런 자를 가리키는 말이다!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "妹よ、わかったか！　必滅の悪とはあのような者を指す言葉だ！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Little sister! She is the evil we must vanquish!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "妹妹，你知道了吧！所謂該死的惡人，是指像她那種的啦！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "น้องเล็ก! พวกนั้นไงล่ะความชั่วร้ายที่เราต้องกำจัด!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Em gái! Đó mới chính là cái ác mà chúng ta phải đánh bại!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "妹妹，你现在明白了吧！必须消灭的邪恶就是指这样的人！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Siehst du, Schwesterchen? So jemanden nennt man das Böse, das man strafen muss!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Regarde, Raphaela ! C'est ce qu'on appelle le Mal de la Destruction !"
L28_1.m_Talk_FRA = L29_1
