L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3900305
L37_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_SERIOUS2"
L37_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L37_1.m_Pos = "C"
L38_1 = "지금 승부가 갈리는 중요한 순간이거든? 방해하지 말아 줄래, 머저리들아?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "あんたたち、勝負が決まる大事な瞬間なんだから、\n邪魔しないでくれる？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "This is a crucial moment for me, okay? So will you two knuckleheads stop bothering me?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "現在是很關鍵時刻！你們這群小笨蛋可以不要妨礙我嗎？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "นี่เป็นช่วงเวลาสำคัญของฉันนะ โอเค้? เจ้าโง่สองคนอย่างพวกเธอช่วยอย่ารบกวนกันได้มั้ย?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Đây là thời khắc quan trọng của tao, hiểu chứ? Hai tên đầu đất chúng mày ngừng làm phiền tao được không?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "现在正是分出胜负的关键时刻。别妨碍我，你们这些蠢货！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Es geht gerade um Sieg oder Niederlage! Aus dem Weg, ihr Würmer!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Nous sommes dans un moment décisif ! Allez jouer ailleurs, les gamins !"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "ALPHA_ACT3_STAGE2_START@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3900305
L38_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_SERIOUS2"
L38_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L38_1.m_Pos = "C"
L39_1 = "자, 지아야. 더 나은 세상을 위해, 복잡한 생각은 그만둬도 돼."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "さあユイ、より良い世界のために、複雑なことは考えなくていい。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Now, Jia? For a better world, stop thinking for yourself."
L38_1.m_Talk_ENG = L39_1
L39_1 = "小佳，為了更好的未來，不要再胡思亂想！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ว่าไงล่ะเจีย? เพื่อโลกที่ดีขึ้น หยุดคิดเพื่อตัวเองซะที"
L38_1.m_Talk_THA = L39_1
L39_1 = "Bây giờ, Jia? Vì một thế giới tốt đẹp hơn, hãy ngừng suy nghĩ cho bản thân."
L38_1.m_Talk_VTN = L39_1
L39_1 = "那么，小佳。为了更好的世界，放弃自我吧。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "So, Jia. Für eine bessere Welt. Du musst nicht mehr grübeln."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Allez, Jia. Ne complique pas les choses... Pour un monde meilleur."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "ALPHA_ACT3_STAGE2_START@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3900305
L39_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_SERIOUS2"
L39_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L39_1.m_Pos = "C"
L40_1 = {}
L41_1 = 1.4
L42_1 = 1.4
L40_1[1] = L41_1
L40_1[2] = L42_1
L39_1.m_CharScale = L40_1
L40_1 = 0.1
L39_1.m_CharScaleTime = L40_1
L40_1 = "더 나은 세상을 위해, 내 목소리를 받아들여."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "より良い世界のために、私の声を受け入れなさい。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "For a better world, listen and follow my voice."
L39_1.m_Talk_ENG = L40_1
L40_1 = "為了更好的未來，聽我的聲音！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เพื่อโลกที่ดีขึ้น จงฟังและทำตามเสียงของฉัน"
L39_1.m_Talk_THA = L40_1
L40_1 = "Vì một thế giới tốt đẹp hơn, hãy lắng nghe và làm theo tiếng nói của ta."
L39_1.m_Talk_VTN = L40_1
L40_1 = "为了更好的世界，接受我的声音！接受我声音的指引！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Für eine bessere Welt. Höre auf meine Stimme."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Écoute-moi... Pour un monde meilleur."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
