L49_1.m_Face = "UNIT_SERIOUS"
L49_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L50_1 = "L_M_I"
L49_1.m_Pos = L50_1
L50_1 = "리더! 정신차려요!!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "リーダー！　しっかりしてください！！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Leader! Snap out of it!!"
L49_1.m_Talk_ENG = L50_1
L50_1 = "老大！你振作一點！！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ท่านผู้นำ! ตั้งสติไว้!"
L49_1.m_Talk_THA = L50_1
L50_1 = "Thủ Lĩnh! Hãy cứng rắn lên!!"
L49_1.m_Talk_VTN = L50_1
L50_1 = "队长！清醒下！！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Anführerin! Kommen Sie zu sich!!!"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Chef ! Reprenez vos esprits !"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "ALPHA_ACT3_STAGE2_START@150#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3900305
L50_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_Face = "UNIT_SERIOUS"
L50_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_04"
L50_1.m_CharStrID = "SEAROM_ALPHA_NULL_NULL"
L51_1 = "R_M_I"
L50_1.m_Pos = L51_1
L51_1 = "악당한테 휘둘리지 마! 리더는 누구보다 가면 카운터처럼 할 수 있잖아!!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "悪党に振り回されないで！\nリーダーは誰よりも仮面カウンターのように強い人だよ！！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Don’t let her win! You're the closest person I know to the Masked Counter!!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "不可以任由反派擺布！老大你可以的！你就跟蒙面制裁者一樣厲害！！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "อย่าปล่อยให้เธอชนะนะคะ! ในบรระดาคนที่ฉันรู้จัก คุณใกล้เคียงหน้ากากเคาน์เตอร์ที่สุดแล้วนะคะ!!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Đừng để cô ta thắng! Chị là người gần giống nhất với Counter Giấu Mặt mà em biết!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "别被那个坏蛋控制了！队长可是比任何人都像假面制裁者的人！！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Lass dich nicht mitreißen, Anführerin! Du kannst doch ein besserer Maskierter Counter sein als jeder andere!!!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Ne l'écoute pas ! Tu peux devenir un Counter Masqué !"
L50_1.m_Talk_FRA = L51_1
