L7_1.m_CharStrID = "CHOI_ALPHA_NULL_SHORT"
L7_1.m_Pos = "L"
L8_1 = "저 실험체들보다 호흡은 우리가 더 잘 맞는다! 밀어붙이는 거다, 동생이여!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "あの実験体たちより私たちのほうが動きがいい！\n追い込んでやろうじゃないか、妹よ！"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Our teamwork seems better than that of those things. Let’s keep pressuring them, little sister!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "我們的默契贏過那些複製人！聯手出擊吧，妹妹！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เราประสานกระบวนท่ากันได้ดีกว่าพวกนั้นนะ มากดดันพวกมันกันต่อเถอะ น้องเล็ก!"
L7_1.m_Talk_THA = L8_1
L8_1 = "Kỹ năng làm việc theo nhóm của chúng ta có vẻ tốt hơn những thứ đó. Hãy tiếp tục gây áp lực lên chúng, em gái à!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "我们的配合比那些实验体们更好！继续攻击，妹妹！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Wir sind besser eingespielt als diese Testsubjekte! Schwesterchen, üben wir Druck aus!"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Nous sommes d'une efficacité parfaite pour ce qui est du travail d'équipe ! Plus que ces clones ratés, en tout cas ! À l'attaque, Raphaela !"
L7_1.m_Talk_FRA = L8_1
