L29_1 = "마침내 손에 넣었어! 최강의 기물을!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ついに手に入れたわ！　最強の駒を！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "She’s finally mine! The most powerful pawn!!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "最強棋子！終於到手了！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ในที่สุดเธอก็เป็นของฉันแล้ว! เบี้ยที่ทรงพลังที่สุด!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Cuối cùng cô ta cũng là của ta! Con tốt mạnh nhất!!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "终于落到我手中了！最强的棋子！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Endlich habe ich sie! Die stärkste Schachfigur!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "J'ai enfin entre mes mains la pièce la plus puissante !"
L28_1.m_Talk_FRA = L29_1
