L33_1 = "ALPHA_ACT3_STAGE2_START@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3900305
L32_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L33_1 = "체스에서 왕은 강할 필요가 없지! 어차피 무엇이든 잘하는 여왕이 있으니까!!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "チェスでキングが強くなる必要はない！\n何でもできるクイーンがいるからね！！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "In chess, the king does not need to be strong! Because the queen can accomplish anything!!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "在西洋棋的世界裡，國王不強也無所謂！反正有什麼都強的皇后！！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "หมากรุกน่ะ คิงไม่ต้องแข็งแกร่งก็ได้! เพราะควีนทำได้ทุกอย่างอยู่แล้วไงล่ะ!!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Trong cờ vua, quân vua không cần phải mạnh! Bởi vì quân hậu có thể làm được bất cứ điều gì!!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "在国际象棋中国王没必要最强！因为有无所不能的皇后！！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Der König braucht im Schach nicht stark zu sein! Er hat sowieso die Königin, die alles gut kann!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Aux échecs, le roi n'a pas besoin d'être fort ! Car la reine est capable de tout faire !"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "ALPHA_ACT3_STAGE2_START@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3900305
L33_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L34_1 = "지아야, 이제 아버지랑 약속한 대로 널 회장으로 만들어 줄게."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ユイ、父さんと約束したとおり、あんたを会長にしてあげる。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Jia, as I promised my father, I’ll make you the President."
L33_1.m_Talk_ENG = L34_1
L34_1 = "小佳，我會遵守跟爸的約定，讓你當上會長。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เจีย อย่างที่ฉันสัญญากับพ่อไว้นะ ฉันจะทำให้เธอเป็นประธาน"
L33_1.m_Talk_THA = L34_1
L34_1 = "Jia, như tao đã hứa với cha, tao sẽ cho mày làm Chủ Tịch."
L33_1.m_Talk_VTN = L34_1
L34_1 = "小佳，现在我就完成与父亲的约定，让你成为会长。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Jia, ich mache dich nun zur Vorsitzenden, so wie ich es meinem Vater versprach."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Jia, je te nomme désormais Présidente. Comme le voulait papa."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
