L37_1 = "ALPHA_ACT3_STAGE2_START@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3900305
L36_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_SERIOUS2"
L36_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_04"
L36_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L37_1 = "L_M_I"
L36_1.m_Pos = L37_1
L37_1 = "날 위해, 알파트릭스를 송두리째 씹어 삼키기 위해 뼈가 부서지도록 일하는 거야."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "私のために、アルファトリックスを根こそぎ奪い取るために、\n馬車馬のごとく働くのよ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "You will now work your fingers to the bone for me until I take over Alphatrix!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "而接下來，你就要努力為我，為吞吃掉阿爾法崔克斯而拼命工作。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "จากนี้เธอก็ต้องทุ่มเททำงานให้ฉันจนกว่าฉันจะยึดอัลฟาทริกซ์ได้!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Bây giờ hãy cứ bận rộn một lát trong khi tao tiếp quản Alphatrix!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "为了我，为了连根拔起阿尔法崔克斯集团，你要工作到粉身碎骨。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Du wirst Knochenarbeit leisten, mir zuliebe, und damit du Alphatrix komplett und restlos einnehmen kannst ..."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Fais tout ce que tu peux pour anéantir Alphatrix pour moi."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "ALPHA_ACT3_STAGE2_START@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3900305
L37_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_SERIOUS2"
L37_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L37_1.m_Pos = "L"
L37_1.m_Crash = 10
L38_1 = "자, 그러면 목격자를 처리해야겠네. 애초에 그걸 위해 불러들인 거기도 하고."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "さあ、次は目撃者を処理しないとね。そもそも、そのために呼び寄せたのだし。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Now, it’s time to get rid of loose ends. That’s why I brought all of you here in the first place."
L37_1.m_Talk_ENG = L38_1
L38_1 = "不過現在必須先處理掉目擊者！一開始會找他們來，也是因為要把他們處理掉。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ทีนี้ก็ได้เวลาปิดฉากแล้ว แบบนี้ไงล่ะฉันถึงพาทุกคนมารวมกันที่นี่"
L37_1.m_Talk_THA = L38_1
L38_1 = "Bây giờ, đã đến lúc thoát khỏi những kết thúc không chắc chắn. Đó là lý do tại sao ngay từ đầu tao đã đưa tất cả chúng mày tới đây."
L37_1.m_Talk_VTN = L38_1
L38_1 = "那么，现在轮到处理这些目击者了。原本也是为了这个目的，才把他们都叫到这里来。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "So, und nun werde ich die Augenzeugen eliminieren. Deshalb habe ich euch überhaupt hergerufen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Et maintenant, il ne me reste plus qu'à éliminer les témoins. C'est d'ailleurs pour ça que je vous ai fait venir !"
L37_1.m_Talk_FRA = L38_1
