L40_1.m_Pos = "R"
L40_1.m_Crash = 10
L41_1 = "오, 오빠……. 이제 어떡할 거야?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "お、お兄ちゃん……どうするの？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "G-Gabriel... What do we do now?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "哥哥……現在怎麼辦？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "กะ-กาเบรียล... เอาไงดีทีนี้?"
L40_1.m_Talk_THA = L41_1
L41_1 = "G-Gabriel... Chúng ta phải làm gì bây giờ?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "哥、哥哥……现在该怎么办？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "B-Brüderchen ... Was nun?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Gabriel... Qu'est-ce qu'on doit faire ?"
L40_1.m_Talk_FRA = L41_1
