L43_1 = "사나이는, 적에게 등을 보이지 않는 법."
L42_1.m_Talk_KOREA = L43_1
L43_1 = 0.05
L42_1.m_fTalkTime = L43_1
L43_1 = "男たる者、敵に背を向けぬもの。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "A real man doesn’t turn his back on his enemies."
L42_1.m_Talk_ENG = L43_1
L43_1 = "男子漢是不會輕易向敵人示弱的！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "คนจริงไม่หันหลังให้ศัตรู"
L42_1.m_Talk_THA = L43_1
L43_1 = "Một người đàn ông đích thực không chạy trốn khỏi kẻ thù của mình."
L42_1.m_Talk_VTN = L43_1
L43_1 = "男子汉绝对不会向敌人屈服。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ein wahrer Mann zeigt nie seinen Rücken."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Un vrai homme ne bat jamais en retraite."
L42_1.m_Talk_FRA = L43_1
