L44_1.m_Face = "UNIT_HATE"
L45_1 = "THEMA_ALPHATRIX"
L44_1.m_StartBGMFileName = L45_1
L44_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_04"
L44_1.m_CharStrID = "CHOI_ALPHA_NULL_SHORT"
L45_1 = "C_L_M_I"
L44_1.m_Pos = L45_1
L45_1 = "대답은 정해져 있다! 동료를 우롱하는 악에게 심판을 내려 주지!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "答えは決まっている！　仲間を愚弄する悪に裁きを下してやろう！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "There’s only one thing I can do! I will punish the evil who mocks my comrades!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "答案就是！必須審判愚弄夥伴的壞人！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ที่ข้าทำได้มีเพียงอย่างเดียว! ข้าจะลงทัณฑ์ความชั่วร้ายที่กลั่นแกล้งสหายข้า!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Chỉ có một điều anh có thể làm! Anh sẽ xử lý kẻ ác đã làm đồng đội của anh đau khổ!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "答案很简单！我要让愚弄同伴的邪恶获得审判！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Die Antwort liegt auf der Hand! Wir werden das Böse richten, das unsere Verbündeten verhöhnt!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Il n'y a qu'une seule chose à faire ! Punir le Mal qui méprise nos camarades !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
