L45_1[L46_1] = L47_1
L46_1 = "앗! 역시 그렇지! 나도 그 말 하려고 했으니까!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "おっ！　やっぱりそうだね！　私もそれを言おうとした！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Huh?! I knew you’d say that! I was going to say the same thing!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "我就知道！我剛也想講那句台詞！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "หือ?! กะแล้วต้องพูดงี้! ฉันกำลังจะพูดพอดีเลย!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Huh?! Em biết thừa anh sẽ nói thế! Em đang định nói như vậy!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "啊！果然是这样！我正想这么说！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Oh! Stimmt genau! Das wollte ich auch sagen!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Exactement ! C'est ce que j'allais dire !"
L45_1.m_Talk_FRA = L46_1
