L1_1[L2_1] = L3_1
L2_1 = "가면 카운터 시즈의 외침으로 주박에서 풀려나는 동료와 같은 전개……!"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "仮面カウンターシージの叫びで呪縛から放たれる味方のような展開……！"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Just like how the Masked Counter’s Siege shout freed his comrades from the curse...!"
L1_1.m_Talk_ENG = L2_1
L2_1 = "蒙面制裁者裡面的經典場面嗎！大吼一聲後，夥伴就得釋放……!"
L1_1.m_Talk_TWN = L2_1
L2_1 = "เหมือนที่หน้ากากเคาน์เตอร์ตะโกนปลดปล่อยสหายจากคำสาปเลย...!"
L1_1.m_Talk_THA = L2_1
L2_1 = "Cũng giống như Counter Giấu Mặt với kỹ năng Bao Vây đã giải thoát đồng đội của mình khỏi lời nguyền...!"
L1_1.m_Talk_VTN = L2_1
L2_1 = "伴随着假面制裁者的不屈怒吼，把伙伴从诅咒中拯救而出的剧情展开……！"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Eine Story, in der die Verbündete durch die Rufe des Maskierten Counters aus dem Bann befreit wird ...!"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Pour libérer mes camarades de l'emprise grâce au cri des assaillants du Counter Masqué...!"
L1_1.m_Talk_FRA = L2_1
