L3_1 = "ALPHA_ACT3_STAGE2_START@202#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 202
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3900305
