L3_1[1] = L4_1
L3_1[2] = L5_1
L2_1.m_CharScale = L3_1
L2_1.m_CharScaleTime = 0.01
L3_1 = "으으……! 실장님의 원수를 갚기 위해 불타오르는 혼을 각성한 오새롬!! 참전한다!!"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "うぅ……！　室長の仇を討つために、\n燃え上がる魂を覚醒させたケンドウ・アサネ！！　参戦するわ！！"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Eergh...! I, Oh Saerom, awakened by the burning soul of vengeance for Chief, will also join you!!"
L2_1.m_Talk_ENG = L3_1
L3_1 = "唔……！現在熱血沸騰的吳芷倫參戰！！我要替室長報仇～～！"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ย๊าก...! วิญญาณที่ลุกโชนด้วยความปรารถนาจะล้างแค้นให้หัวหน้าได้ปลุกพลังของฉัน โอ แซรม ขึ้นมาแล้ว!!"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ơ ...! Tôi, Oh Saerom, được đánh thức bởi tâm nguyện báo thù cháy bỏng cho Trưởng Phòng, cũng sẽ tham gia cùng các bạn!!"
L2_1.m_Talk_VTN = L3_1
L3_1 = "呃呃……！为了给室长报仇，觉醒燃烧之魂的绫音！！参战！！"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Urgh ...! Ich, Oh Saerom, habe meinen brennenden Kampfgeist wiedererlangt, um Rache für die Direktorin zu üben!!! Ich kämpfe mit!!!"
L2_1.m_Talk_DEU = L3_1
L3_1 = "L'esprit enflammé d'Oh Saerom s'est réveillé pour venger Jin ! Au combat !"
L2_1.m_Talk_FRA = L3_1
