L7_1[1] = L8_1
L7_1[2] = L9_1
L5_1[L6_1] = L7_1
L6_1 = "자, 잠깐! 네 동료라고! 그딴 애들 만화에 짜맞추지 마!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "は？　あいつもあんたの仲間でしょ！　そんなガキの漫画に出てくる悪党じゃないでしょ！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "W-wait! She’s your leader! Stop pretending like this is some childish cartoon!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "先等一下！她可是你們的夥伴！勸你們少看那些騙小孩子漫畫吧！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ดะ-เดี๋ยวสิ! นั่นท่านผู้นำพวกเธอนะ! อย่ามาทำเป็นการ์ตูนเด็กกันแบบนี้สิ!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Đ-đợi đã! Nó là thủ lĩnh của các người! Đừng giả vờ như đây là một bộ phim hoạt hình trẻ con!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "等、等下！她可是你的队长！别用漫画的幼稚剧情乱来！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "W-warte mal! Sie ist eure Verbündete! Denkt doch nicht wie eine Kinderzeichentrickserie!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "A-Attends, tes camarades ? Tu te crois dans un dessin animé là ?"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "ALPHA_ACT3_STAGE2_START@206#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 3900305
L6_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L6_1.m_bWaitClick = true
