L6_1.m_Face = "UNIT_HATE"
L6_1.m_CharStrID = "SEAROM_ALPHA_NULL_NULL"
L6_1.m_Pos = "R"
L7_1 = 40
L6_1.m_Crash = L7_1
L7_1 = "애들 만화가 뭐가 나빠! 당신은 어린 시절도 없었어?!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "子どもの漫画のどこが悪いの！　あんたも昔は子どもだったんでしょ！？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "What’s wrong with kid’s cartoons?! Haven’t you watched one as a kid?!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "騙小孩的漫畫又怎樣！你沒童年嗎？！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "การ์ตูนเด็กแล้วมันทำไม?! ตอนเด็กๆ ไม่เคยดูรึไง?!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Phim hoạt hình dành cho trẻ em thì sao nào?! Lúc còn nhỏ cô chưa xem à?!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "漫画有什么不好！你难道没有童年吗？！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Was ist so schlecht an Kinderzeichentrickserien? Waren Sie noch nie jung?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Et qu'est-ce que ça peut te faire ? Tu n'as pas de souvenirs d'enfance ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
