L9_1 = "ALPHA_ACT3_STAGE2_START@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3900305
L8_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "UNIT_IDLE"
L8_1.m_Face = L9_1
L9_1 = "FX_CUTSCEN_NOISE_RUSTLE_02"
L8_1.m_StartFXSoundName = L9_1
L8_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "죄송하지만, 한 가지 오판을 하셨네요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "申し訳ありませんが、一つ判断を誤りましたね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I’m sorry, but you’ve underestimated them."
L8_1.m_Talk_ENG = L9_1
L9_1 = "不好意思，你誤判一件事。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "โทษทีนะ แต่เธอประมาทพวกนั้นไปหน่อย"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tôi xin lỗi, nhưng cô đã đánh giá thấp họ."
L8_1.m_Talk_VTN = L9_1
L9_1 = "抱歉，但你有一点判断失误。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Tut mir leid, aber Ihnen ist eine Fehleinschätzung unterlaufen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Pardon, mais je crois que vous avez fait une erreur de jugement."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
