L13_1 = "ALPHA_ACT3_STAGE2_START@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3900305
L12_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L12_1.m_Pos = "R"
L13_1 = "저 둘은 바보들이라 평소에는 수준 이하입니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "あの二人はバカなので、そんな理屈は通じませんよ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Those two are stupid as can be under normal circumstances."
L12_1.m_Talk_ENG = L13_1
L13_1 = "那兩個笨蛋平時沒什麼用處。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ในสถานการณ์ทั่วไป สองคนนั้นก็โง่ได้สุดทางจริง"
L12_1.m_Talk_THA = L13_1
L13_1 = "Hai người đó bình thường thì rất ngốc."
L12_1.m_Talk_VTN = L13_1
L13_1 = "那两个人原本就是傻瓜，所以平时的举止有些弱智。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Die beiden sind dumm und sind üblicherweise unter allem Niveau."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Ces deux-là sont plus bêtes que vous ne le pensez."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "ALPHA_ACT3_STAGE2_START@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3900305
L13_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L13_1.m_Pos = "R"
L14_1 = "하지만 분위기에 취하면 보다시피 겁을 상실하고 좋은 엄폐물이 되어 주죠."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "でも今みたいに雰囲気に酔うと、ご覧のとおり調子に乗って良い掩蔽物になってくれます。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "But once they’re in the zone, they lose all sense of fear and become great shields."
L13_1.m_Talk_ENG = L14_1
L14_1 = "但只要沉醉在氣氛當中，就會變身成天不怕地不怕的掩體，就像你看到的那樣。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "แต่พอเอาจริงขึ้นมาละก็ ทั้งคู่จะลืมความกลัวไปหมด และกลายเป็นโล่สุดแกร่ง"
L13_1.m_Talk_THA = L14_1
L14_1 = "Nhưng một khi gặp tình huống, họ sẽ mất hết cảm giác sợ hãi và trở thành tấm khiên tuyệt vời."
L13_1.m_Talk_VTN = L14_1
L14_1 = "可是一旦被激起了斗志，就会变得毫无畏惧，是最好不过的掩体。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Aber wenn sie in Fahrt kommen, verlieren sie jede Furcht, wie sie sehen, und bieten erstklassige Deckung."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Mais lorsqu'il s'agit d'agir, ils n'ont peur de rien, comme vous pouvez le constater. En somme, le bouclier parfait."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "ALPHA_ACT3_STAGE2_START@214#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 214
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3900305
L14_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_HATE"
L14_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L14_1.m_Pos = "L"
L15_1 = "그래서, 너도 네 고용주에게 총을 겨누겠다고? 제정신이 아닌 건 너도 마찬가지 같은데!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "それで、あんたも自分の雇い主に銃口を向けると？\n正気じゃないのはあんたも同じでしょ！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "So, you’re going to shoot your employer as well? You sound just as crazy as them!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "所以你也要把槍瞄準你的雇主嗎？我看你也是腦袋不太正常吧！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "เธอก็เลยจะยิงนายจ้างตัวเองด้วยเหรอ? ฟังดูบ้าไม่แพ้กันเลยนะ!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Vậy là mày định bắn sếp của mình nữa sao? Mày nói điên khùng y như chúng vậy!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "所以，你想对你的雇主开枪吗？看来你也已经疯了！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Also wirst auch du dein Geschoss auf deinen Arbeitgeber richten? Du hast sie auch nicht mehr alle!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Donc toi aussi tu penses tirer sur ton employeur ? Tu ne vaux pas mieux qu'eux !"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
