L17_1 = "ALPHA_ACT3_STAGE2_START@216#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 216
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3900305
L16_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "UNIT_LAUGH"
L16_1.m_Face = L17_1
L16_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L16_1.m_Pos = "C"
L16_1.m_Crash = 10
L17_1 = "별로요. 리더가 저한테 죽을 사람인가요?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "別に。リーダーが私に殺されるような人だと思いますか？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Not really. Do you really think Leader will die to me?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "我還好，你覺得老大會這麼輕易死在我手裡嗎？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ก็ไม่เชิงนะ นี่คิดจริงๆ เหรอว่าท่านผู้นำจะตายเพราะฉันน่ะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Không hẳn vậy. Cô thực sự tưởng rằng Thủ Lĩnh sẽ chết bởi tôi ư?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "哦？队长怎么会轻易死在我的手上？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Na ja. Als ob die Anführerin sich von mir töten lassen würde."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Non, pas vraiment. Cela m'étonnerait qu'elle se fasse tuer par une personne comme moi."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "ALPHA_ACT3_STAGE2_START@217#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 217
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 3900305
L17_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L17_1.m_Pos = "C"
L18_1 = "그러면, 이런 일개 용병 손에 당할까 봐 걱정스러운 사람에게 질투심을 불태웠던 건가요?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "じゃなければ、こんな一介の傭兵にやられそうで心配になるような人に\n嫉妬していたのですか？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Or did you become enraged because you were afraid that a mercenary like me would succeed?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "所以你忌妒的對象，是一個會栽在一個小傭兵手裡的人？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "หรือที่โกรธนี่เพราะกลัวทหารรับจ้างอย่างฉันจะทำสำเร็จนะ?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Hay cô tức giận vì sợ rằng một tên lính đánh thuê như tôi sẽ thành công?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "难道说，你在担心自己羡慕嫉妒的人，死在我这种小佣兵手中吗？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Oder haben Sie etwa vor Eifersucht gebrannt auf jemanden, bei dem Sie sich Sorgen machen müssen, dass er von einem bloßen Söldner wie mir getötet wird?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Dois-je comprendre que vous étiez jalouse d'une personne qui craignait de se faire attaquer par des mercenaires de secondes zones ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "ALPHA_ACT3_STAGE2_START@218#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 218
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3900305
L18_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
