L21_1 = "ALPHA_ACT3_STAGE2_START@220#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 220
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3900305
L20_1.m_CutScenStrID = "ALPHA_ACT3_STAGE2_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_SERIOUS"
L20_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_04"
L20_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L21_1 = "C_L_M_I"
L20_1.m_Pos = L21_1
L21_1 = "리더도 실장님도 부재 중이니 제가 지휘를 대행하겠습니다."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "リーダーも室長も不在なので、私が指揮を代行します。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Since both Leader and Chief are unavailable, I will assume command."
L20_1.m_Talk_ENG = L21_1
L21_1 = "老大和室長都不在，現在由我代為發號施令！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ในเมื่อทั้งหัวหน้าและท่านผู้นำไม่พร้อม ฉันจะออกคำสั่งเอง"
L20_1.m_Talk_THA = L21_1
L21_1 = "Vì cả Thủ Lĩnh và Trưởng Phòng đều không có mặt, tôi sẽ đảm nhận quyền chỉ huy."
L20_1.m_Talk_VTN = L21_1
L21_1 = "队长和室长都不在，所以由我来临时指挥。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Sowohl die Anführerin als auch die Direktorin sind abwesend, also übernehme ich die Führung."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Puisque la chef et Jin ne sont pas là, c'est moi qui prend les commandes."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
